var builder=WebApplication.CreateBuilder(args);builder.Services.AddOpenApi();builder.Services.AddSingleton<PackageStore>();builder.Services.AddHealthChecks();var app=builder.Build();app.MapOpenApi();app.MapHealthChecks("/health");
app.MapPost("/packages",(CreatePackageDto dto,PackageStore s)=>{if(string.IsNullOrWhiteSpace(dto.House)||dto.WeightKg<0||string.IsNullOrWhiteSpace(dto.RecipientAddress))return Results.ValidationProblem(new Dictionary<string,string[]>{{"package",new[]{"Invalid package"}}});return Results.Created("/packages/"+s.Create(dto),s.Get(s.LastId));});
app.MapGet("/packages",(PackageStore s)=>Results.Ok(s.All()));app.MapGet("/packages/{id:int}",(int id,PackageStore s)=>s.Get(id) is { } p?Results.Ok(p):Results.NotFound());app.MapPatch("/packages/{id:int}",(int id,UpdatePackageDto dto,PackageStore s)=>s.Update(id,dto) is { } p?Results.Ok(p):Results.NotFound());app.MapDelete("/packages/{id:int}",(int id,PackageStore s)=>s.Delete(id)?Results.Ok(new{deleted=true}):Results.NotFound());app.Run();
public record CreatePackageDto(string House,double WeightKg,string RecipientAddress);public record UpdatePackageDto(string? House,double? WeightKg,string? RecipientAddress);
public record Package(int Id,string House,double WeightKg,string RecipientAddress,DateTime CreatedAt,DateTime UpdatedAt);
public sealed class PackageStore{readonly Dictionary<int,Package> d=new();int n=0;public int LastId=>n;public int Create(CreatePackageDto x){var now=DateTime.UtcNow;var p=new Package(++n,x.House,x.WeightKg,x.RecipientAddress,now,now);d[n]=p;return n;}public IEnumerable<Package> All()=>d.Values;public Package? Get(int id)=>d.GetValueOrDefault(id);public Package? Update(int id,UpdatePackageDto x){if(!d.TryGetValue(id,out var p))return null;var q=p with {House=x.House??p.House,WeightKg=x.WeightKg??p.WeightKg,RecipientAddress=x.RecipientAddress??p.RecipientAddress,UpdatedAt=DateTime.UtcNow};d[id]=q;return q;}public bool Delete(int id)=>d.Remove(id);}